using System;
using System.Linq;
namespace Touchline {
public static class SetupRevisionTests {
 public static bool Run(){var g=GameFactory.New(181);var names=g.Players.ToDictionary(p=>p.Id,p=>"Name "+p.Id);PlayerEditing.RenameAllBeforeStart(g,names);if(g.Players.Any(p=>p.Name!=names[p.Id]))throw new Exception("Initial player names failed");var c=ClubChoices.Draw(g,"文化型俱乐部","传控足球");if(c.Philosophy!="传控足球"||g.Clubs.Any(x=>!Rules.Philosophies.Contains(x.Philosophy)))throw new Exception("Initial philosophy lost");var p1=g.Squad(c.Id).First();PlayerEditing.RenameOwn(g,p1.Id,"My Player");var outside=g.Players.First(p=>p.ClubId!=c.Id);bool blocked=false;try{PlayerEditing.RenameOwn(g,outside.Id,"No");}catch{blocked=true;}if(!blocked)throw new Exception("Opponent rename permitted");blocked=false;try{PlayerEditing.RenameAllBeforeStart(g,names);}catch{blocked=true;}if(!blocked)throw new Exception("Bulk player rename after start");bool language=L10n.English;try{L10n.English=true;if(L10n.T("理念与战术")!="Philosophy & Tactics"||L10n.T("摆大巴")!="Park the Bus")throw new Exception("English resource missing");L10n.Protect(g);if(!L10n.T(p1.Name+"进球").Contains(p1.Name))throw new Exception("Localized personal name");L10n.English=false;if(L10n.T("摆大巴")!="摆大巴")throw new Exception("Chinese switch failed");}finally{L10n.English=language;L10n.Protect(null);}if(!LocalRuntime.IsBundled("http://127.0.0.1:17845/v1/chat/completions","touchline-local")||LocalRuntime.IsBundled("http://example.com:17845/v1/chat/completions","touchline-local"))throw new Exception("Runtime endpoint detection");return true;}
}
}
